let SCALE=1;function sizeDevice(){const w=document.getElementById('devwrap'),d=document.getElementById('device');if(matchMedia('(max-width:460px)').matches){SCALE=1;d.style.transform='';w.style.width=w.style.height='';return}const nar=matchMedia('(max-width:860px)').matches,tb=nar?document.getElementById('topbar').offsetHeight:0,H=innerHeight-tb-28,W=innerWidth-(nar?20:400);SCALE=Math.min(1,H/896,W/430);d.style.transform=`scale(${SCALE})`;w.style.width=424*SCALE+'px';w.style.height=896*SCALE+'px'}
addEventListener('resize',sizeDevice);
const THEMES=[['dark','Dark'],['light','Light'],['auto','Auto']];let THEME='dark';try{THEME=localStorage.getItem('fore-theme')||'dark'}catch(e){}
