const $=s=>document.querySelector(s),TABS={golfer:[['home','Home','home'],['book','Book','flag'],['lessons','Lessons','cal'],['progress','Progress','trend']],coach:[['today','Today','home'],['calendar','Calendar','cal'],['students','Students','users'],['earnings','Earnings','wallet']]};
const nv=()=>S.nav[S.role];
