 goal:d=>{S.goal=d.id;show('none')},clearf:()=>{S.goal='all';S.q='';S.maxP=0;S.weekend=false;show('none')},
 filters:()=>{const fn=()=>`<h2>Filters</h2><div><label class="l">Price per lesson</label><div class="seg">${[[0,'Any'],[2000,'Under ₹2,000'],[3000,'Under ₹3,000']].map(([v,l])=>`<button data-a="fprice" data-id="${v}" aria-pressed="${S.maxP===v}">${l}</button>`).join('')}</div></div><div class="list"><div class="row"><span class="m t">This weekend</span>${toggle('wk',S.weekend,'This weekend')}</div></div><button class="btn full" data-a="closeS">Show ${filtered().length} coaches</button>`;openSheet(fn)},
