 bkwho:d=>{S.bk.who=d.id;S.bk.pkg=bkOpts()[0].id;show('none')},bkpkg:d=>{S.bk.pkg=d.id;show('none')},bkday:d=>{S.bk.d=+d.id;S.bk.t=null;show('none')},bktime:d=>{S.bk.t=+d.id;show('none')},bkpay:d=>{S.bk.pay=d.id;show('none')},pay:payFlow,
 doneBk:()=>{const n=nv();n.stack=[];n.tab='home';show('pop')},
 chatw:(d)=>{closeSheet();const k=d.c+':'+d.s;S.chats[k]=S.chats[k]||[];go('chat',{id:k})},
 resch:d=>{const l=lesson(d.id);let dd=l.d,tt=null;const fn=()=>{const ts=timesFor(l.coach);return `<h2>Pick a new time</h2><div class="datestrip">${Array.from({length:14},(_,i)=>`<button class="ds" data-a="rd" data-id="${i}" aria-pressed="${dd===i}"><span>${i===0?'Today':WD[dayD(i).getDay()]}</span><b class="num">${dayD(i).getDate()}</b></button>`).join('')}</div><div class="times">${ts.map(t=>{const o=isOpen(l.coach,dd,t);return `<button class="tm num" ${o?'':'disabled'} data-a="rt" data-id="${t}" aria-pressed="${tt===t}">${fT(t)}</button>`}).join('')}</div><button class="btn full" data-a="rgo" ${tt==null?'disabled':''}>Move lesson</button>`};ACT.rd=x=>{dd=+x.id;tt=null;refreshSheet()};ACT.rt=x=>{tt=+x.id;refreshSheet()};ACT.rgo=()=>{if(l.coach==='arjun'){S.open.add(l.d+':'+l.t);S.open.delete(dd+':'+tt)}l.d=dd;l.t=tt;closeSheet();toast('Lesson moved');show('none');if(l.coach==='arjun')event('coach',{i:'clock',t:`${stud(l.student).first} moved a lesson`,b:`Now ${dLbl(dd)}, ${fT(tt)}`})};openSheet(fn)},
 cancel:d=>{const l=lesson(d.id),free=l.d*1440+l.t-NOW>=1440;openSheet(()=>`<h2>Cancel this lesson?</h2><p class="muted">${l.payState==='due'?'You have not been charged for this lesson.':l.fromPack?(free?'This lesson goes back into your package.':'This lesson is under 24 hours away, so it counts as used. You could move it instead.'):free?`${money(l.price)} goes back to you within 3 to 5 working days.`:'This lesson is under 24 hours away, so it cannot be refunded. You could move it instead.'}</p><button class="btn danger full" data-a="doCancel" data-id="${l.id}">Cancel lesson</button><button class="btn sec2 full" data-a="closeS">Keep lesson</button>`)},
 doCancel:d=>{const l=lesson(d.id);if(l.fromPack&&l.d*1440+l.t-NOW<1440){const p=packFor(l);if(p)p.used++}l.status='cancelled';l.fresh=false;if(l.coach==='arjun')S.open.add(l.d+':'+l.t);closeSheet();if(S.role==='golfer'&&l.coach==='arjun')event('coach',{i:'x',t:`${stud(l.student).first} cancelled`,b:`${dLbl(l.d)}, ${fT(l.t)} is open again`});back()},
 rate:d=>{const l=lesson(d.id);let v=0;const fn=()=>`<h2>How was your lesson?</h2><div class="stars" style="justify-content:center">${[1,2,3,4,5].map(n=>`<button class="${n<=v?'on':''}" data-a="star" data-n="${n}" aria-label="${n} stars">${ic('star')}</button>`).join('')}</div><button class="btn full" data-a="sendRate" ${v?'':'disabled'}>Send rating</button>`;ACT.star=x=>{v=+x.n;refreshSheet()};ACT.sendRate=()=>{l.rated=v;closeSheet();toast('Thanks. That helps other golfers.');show('none');if(l.coach==='arjun')event('coach',{i:'star',t:`New review, ${v} stars`,b:`${stud(l.student).first}'s verified lesson`})};openSheet(fn)},
 addRound:()=>{let sc=88,pu=33;const fn=()=>`<h2>Add a round</h2><div><label class="l" for="rc">Course</label><input class="fld" id="rc" value="Aravalli Links"></div><div class="row"><span class="m t">Score</span><span class="stepper"><button data-a="st" data-k="s" data-n="-1" aria-label="Less">−</button><b class="num">${sc}</b><button data-a="st" data-k="s" data-n="1" aria-label="More">+</button></span></div><div class="row"><span class="m t">Putts</span><span class="stepper"><button data-a="st" data-k="p" data-n="-1" aria-label="Less">−</button><b class="num">${pu}</b><button data-a="st" data-k="p" data-n="1" aria-label="More">+</button></span></div><button class="btn full" data-a="saveR">Save round</button>`;ACT.st=x=>{const c=$('#rc')?.value;if(x.k==='s')sc+=+x.n;else pu+=+x.n;refreshSheet();if($('#rc'))$('#rc').value=c};ACT.saveR=()=>{(S.rounds[S.who]=S.rounds[S.who]||[]).push([$('#rc').value||'Round',sc,pu,0]);closeSheet();toast('Round saved');show('none')};openSheet(fn)},
 tog:d=>{if(d.id==='approve')S.approveNew=!S.approveNew;else if(d.id==='wk'){S.weekend=!S.weekend;refreshSheet()}else if(d.id==='nparent')S.noteDraft.parent=!S.noteDraft.parent;else if(d.id==='fail'){S.failNext=!S.failNext;chrome();if(sheetFn)refreshSheet();return}else S.toggles[d.id]=!S.toggles[d.id];show('none')},
